(function() {
    'use strict';

    function normaliseNumber(rawValue) {
        if (!rawValue) return NaN;
        return Number(String(rawValue).replace(/[^0-9.,-]/g, '').replace(',', '.'));
    }

    function updateOldPriceVisibility(product) {
        var oldPriceWrapper = product.querySelector('.js-store-prod-price-old');
        if (!oldPriceWrapper) return;

        var oldPriceValue = oldPriceWrapper.querySelector('.js-store-prod-price-old-val');
        var currentPriceValue = product.querySelector('.js-store-prod-price-val');

        var oldPriceText = oldPriceValue ? oldPriceValue.textContent.trim() : '';
        var currentPriceText = currentPriceValue ? currentPriceValue.textContent.trim() : '';

        if (!oldPriceText) {
            oldPriceWrapper.style.display = 'none';
            return;
        }

        var oldPrice = normaliseNumber(oldPriceText);
        var currentPrice = normaliseNumber(currentPriceText);

        if (!isFinite(oldPrice) || !isFinite(currentPrice) || oldPrice <= currentPrice) {
            oldPriceWrapper.style.display = 'none';
        } else {
            oldPriceWrapper.style.display = '';
        }
    }

    function updateBuyButton(product, options) {
        var btnLabel = product.querySelector('.js-store-prod-buy-btn-txt');
        if (btnLabel && options && options.buyBtnTitle) {
            btnLabel.textContent = options.buyBtnTitle;
        }
    }

    function applyTypography(product, options) {
        if (!options || !options.typo) return;

        if (options.typo.descrColor) {
            var infoBlock = product.querySelector('.js-store-prod-text');
            if (infoBlock) infoBlock.style.color = options.typo.descrColor;
        }
    }

    function revealProduct(product) {
        var info = product.querySelector('.js-store-single-product-info');
        if (info && info.style.display === 'none') {
            info.style.display = '';
        }

        var preloader = product.querySelector('.t-store__single-prod-preloader');
        if (preloader && preloader.parentNode) {
            preloader.parentNode.removeChild(preloader);
        }
    }

    function revealSlider(record) {
        var slider = record.querySelector('.t-slds');
        if (slider && slider.style.visibility === 'hidden') {
            slider.style.visibility = '';
        }
    }

    function enhanceGallery(record) {
        record.querySelectorAll('.t-slds__item img').forEach(function(node) {
            node.loading = 'lazy';
        });
    }

    function markInitialised(product) {
        product.setAttribute('data-store-initialized', 'true');
    }

    function initSlider(slider) {
        if (!slider || slider.dataset.sliderInitialized === 'true') return;

        var wrapper = slider.querySelector('.t-slds__items-wrapper');
        if (!wrapper) return;

        var slides = Array.prototype.slice.call(wrapper.querySelectorAll('.t-slds__item'));
        if (!slides.length) return;

        slider.dataset.sliderInitialized = 'true';
        wrapper.style.display = 'block';

        slides.forEach(function(slide) {
            slide.style.float = 'none';
            slide.style.width = '100%';
        });

        var bullets = Array.prototype.slice.call(slider.querySelectorAll('[data-slide-bullet-for]'));
        var controls = Array.prototype.slice.call(slider.querySelectorAll('[data-slide-direction]'));
        var allowCycle = wrapper.getAttribute('data-slider-with-cycle') !== 'false';
        var activeIndex = 0;

        slides.forEach(function(slide, position) {
            if (slide.classList.contains('t-slds__item_active')) {
                activeIndex = position;
            }
        });

        function applyActiveState(index) {
            slides.forEach(function(slide, position) {
                var isActive = position === index;
                slide.classList.toggle('t-slds__item_active', isActive);
                slide.style.display = isActive ? 'block' : 'none';
            });

            bullets.forEach(function(bullet) {
                var bulletIndex = parseInt(bullet.getAttribute('data-slide-bullet-for'), 10) - 1;
                bullet.classList.toggle('t-slds__bullet_active', bulletIndex === index);
            });

            activeIndex = index;
        }

        function show(index) {
            if (index < 0) {
                index = allowCycle ? slides.length - 1 : 0;
            }

            if (index >= slides.length) {
                index = allowCycle ? 0 : slides.length - 1;
            }

            applyActiveState(index);
        }

        controls.forEach(function(control) {
            control.addEventListener('click', function(event) {
                event.preventDefault();
                var direction = control.getAttribute('data-slide-direction');
                show(activeIndex + (direction === 'right' ? 1 : -1));
            });
        });

        bullets.forEach(function(bullet) {
            bullet.addEventListener('click', function(event) {
                event.preventDefault();
                var bulletIndex = parseInt(bullet.getAttribute('data-slide-bullet-for'), 10) - 1;
                if (!isNaN(bulletIndex)) {
                    show(bulletIndex);
                }
            });
        });

        slider.style.visibility = '';
        show(activeIndex);
    }

    function initAllSliders() {
        var sliders = document.querySelectorAll('.t-slds');
        sliders.forEach(initSlider);
    }

    function initAllProducts() {
        var products = document.querySelectorAll('.js-store-product_single');
        products.forEach(function(product) {
            if (product.getAttribute('data-store-initialized') === 'true') return;

            var record = product.closest('[id^="rec"]');
            window.t_store_oneProduct_init(record, {});
        });
    }

    function onReady(callback) {
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', callback);
        } else {
            callback();
        }
    }

    window.t_store_oneProduct_init = function(recordTarget, options) {
        var record = typeof recordTarget === 'string' ? document.getElementById('rec' + recordTarget) : recordTarget;
        if (!record) return;

        var product = record.querySelector('.js-store-product_single');
        if (!product) return;

        revealProduct(product);
        revealSlider(record);
        enhanceGallery(record);
        updateBuyButton(product, options || {});
        applyTypography(product, options || {});
        updateOldPriceVisibility(product);
        markInitialised(product);
    };

    onReady(function() {
        initAllProducts();
        initAllSliders();
    });
})();
